const {
	getState,
	itemTypeName,
	rows
} = options;
const state = getState();
const hidden =  state.grid.selectedRows.length > 1;
if (hidden) {
	return { hidden };
}

const rowId = state.grid.selectedRows[0];
const isNew = ArasModules.item.isNew(itemTypeName, rowId);
const isLocked = !!rows.get(rowId, 'locked_by_id');
const isPromoteDisabled = window.isFunctionDisabled(itemTypeName, 'Promote');
const disabled = isNew || isLocked || isPromoteDisabled;

return {
	disabled,
	hidden: false
};
